insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('b8b6da68-3cce-5c31-a362-e882a6d91854', 'wg8-narrative-writing-p05', (select id from public.skills where slug = 'write-g8-narrative-writing'), null,
        '6-8', $q$The Letters in the Attic$q$, $q$(1) Our history teacher, Mr. Nakamura, assigned a project about a family member's past, and I had no idea where to start. (2) My mom suggested I look in the attic. (3) The attic was hot and dusty. (4) Behind a stack of holiday decorations, I found a metal box with a rusty latch. (5) Inside was a bundle of letters tied with faded blue ribbon.

(6) The top letter was dated 1912. (7) It was written by my great-great-grandmother, Giulia, to her sister back in Sicily. (8) She described her first week working in a textile mill in Massachusetts. (9) She wrote that the machines were so loud she could not hear her own voice. (10) She also wrote that she was saving every coin to bring her sister to America.

(11) I sat on the attic floor and read until the light through the small window turned orange. (12) My mom climbed the ladder to check on me. (13) I told her about the letters. (14) She said she knew about them.

(15) I presented my project to the class. (16) I got an A.$q$, 'draft')
