  ('e62744d0-5ec6-568e-ae6f-7f1934ba20ca', null, (select id from public.skills where slug = 'write-g8-sentence-structure'), null, 'medium',
   $q$Which group of words is a complete sentence rather than a fragment?$q$, $q$[{"text":"The students who designed the solar oven during the summer workshop at the community college.","is_correct":false,"misconception_token":"long-subject-no-verb"},{"text":"After designing a solar oven during the summer workshop at the community college.","is_correct":false,"misconception_token":"dependent-phrase-as-sentence"},{"text":"Students designing a solar oven during the summer workshop at the community college.","is_correct":false,"misconception_token":"participle-as-main-verb"},{"text":"The students designed a solar oven during the summer workshop at the community college.","is_correct":true}]$q$::jsonb, $q$The students designed a solar oven during the summer workshop at the community college.$q$, $q$"The students designed a solar oven" has a subject and a main verb, so the group of words is complete. In the "who designed" choice, "designed" belongs to the relative clause, and the subject "students" never gets its own verb.$q$, 'draft', null)
