  ('f29d696f-f150-51e2-a954-6ea6a47c0023', null, (select id from public.skills where slug = 'write-g8-sentence-structure'), null, 'medium',
   $q$Read the sentence: "Last summer, Omar volunteered at the food bank, organized a book drive, and is coaching a youth soccer team." Which revision is parallel?$q$, $q$[{"text":"Last summer, Omar volunteered at the food bank, organized a book drive, and he coached a youth soccer team.","is_correct":false,"misconception_token":"clause-in-series"},{"text":"Last summer, Omar volunteered at the food bank, organized a book drive, and coached a youth soccer team.","is_correct":true},{"text":"Last summer, Omar volunteered at the food bank, organizing a book drive, and coached a youth soccer team.","is_correct":false,"misconception_token":"mixed-verb-forms"},{"text":"Last summer, Omar volunteers at the food bank, organized a book drive, and coached a youth soccer team.","is_correct":false,"misconception_token":"tense-shift-in-series"}]$q$::jsonb, $q$Last summer, Omar volunteered at the food bank, organized a book drive, and coached a youth soccer team.$q$, $q$"Volunteered, organized, and coached" are all past tense verbs that share the subject Omar, which fits "Last summer." Adding "he" before the last verb breaks the pattern by turning the last item into a clause.$q$, 'draft', null)
