-- Passage wg8-writing-with-evidence-p05
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('8ca33250-10a4-57a2-af28-2f3bad0a991c', 'wg8-writing-with-evidence-p05', (select id from public.skills where slug = 'write-g8-writing-with-evidence'), null,
        '6-8', $q$Draft: What Rest Days Do$q$, $q$(1) In "Rest Days Win Races," Kofi Mensah argues that young runners improve faster when they take regular rest days. (2) Mensah explains that muscles grow stronger during rest, not during the workout itself. (3) He describes a study in which two groups of middle school runners trained for eight weeks. (4) One group ran every day, and the other rested two days a week. (5) Mensah reports that the group that rested "cut an average of forty seconds from their mile times," while the other group improved by only twelve seconds. (6) ____.

(7) Mensah also points out that rest protects runners from injury. (8) In the study, four runners in the everyday group hurt their shins, but only one runner in the rest group did. (9) My friend Ji-woo runs every day and has never been hurt. (10) Mensah's evidence shows that rest helps runners both get faster and stay healthy.$q$, 'draft')
on conflict (id) do update set title = excluded.title, body = excluded.body
where public.passages.status = 'draft';
